SELECT * FROM (SELECT CASE WHEN budget >= 3077000 THEN 'high' WHEN budget >= 1541000 THEN 'mid' ELSE 'low' END budget_bucket, SUM(CASE WHEN dept_name = 'HR' THEN 1 ELSE 0 END) hr_count, MAX(budget) max_budget FROM departments WHERE location = 'Bangkok' GROUP BY CASE WHEN budget >= 3077000 THEN 'high' WHEN budget >= 1541000 THEN 'mid' ELSE 'low' END) t WHERE max_budget > 1384000 ORDER BY hr_count DESC, max_budget DESC;
